import os, sys, importlib.util

def _get_version_from_source(module_name):
    """Read a module's __init__ and extract __version__ without importing it."""
    spec = importlib.util.find_spec(module_name)
    if spec is None or spec.origin is None:
        return None
    try:
        with open(spec.origin, "r", encoding="utf-8") as fh:
            src = fh.read()
    except Exception:
        return None
    # Find the first assignment to __version__ that looks like 'x.y.z' or "x.y.z"
    import re
    m = re.search(r'__version__\s*=\s*["\']([^"\']+)["\']', src)
    if m:
        return m.group(1)
    return None

_version = _get_version_from_source("setuptools")
if _version is not None:
    print("system setuptools", _version)
else:
    print("system setuptools unknown", file=sys.stderr)

import os, sys

def ffloor(v):
    """Rust f64::floor: total, returns a float, inf->inf, nan->nan."""
    if v != v or v == float('inf') or v == float('-inf'): return v
    if v >= 0.0:
        return int(v) if v == int(v) else int(v)
    else:
        iv = int(v)
