    elif x == 0.0:
        mod = 0.0
    elif x == float('inf') or x == float('-inf') or y == float('inf') or y == float('-inf'):
        mod = float('nan')
    else:
        # manual fmod: x - trunc(x/y)*y, trunc toward zero
        q = x / y
        if q >= 0.0:
            tq = int(q)
        else:
            tq = -int(-q)
        mod = x - tq * y
    div = (x - mod) / y
    if mod != 0.0 and (mod < 0.0) != (y < 0.0):
        div -= 1.0
    if div == 0.0:
        return 0.0 if (x < 0) == (y < 0) else -0.0
    fd = ffloor(div)
    return fd + 1.0 if div - fd > 0.5 else fd

