def isqrt(n):
    """Integer square root using Newton's method with 53-bit precision arithmetic."""
    if n < 0:
        raise ValueError("square root not defined for negative numbers")
    if n == 0:
        return 0
    # Initial approximation using float (exact for n up to 2^53)
    x = float(n)
    y = (x + 1.0) / 2.0
    # Refine using integer arithmetic to avoid precision issues
    while True:
        # Integer division approximates Newton step
        x = (x + n // x) // 2
        if x >= y:
            break
        y = x
    return int(x + 1)

