def isqrt(n):
    if n < 0:
        raise ValueError("square root of negative number")
    if n == 0:
        return 0
    # Use float approximation to get a good initial guess
    x = float(n)
    y = (x + 1) / 2
    while y < x:
        x = y
        y = (x + n // x) // 2
    return int(x)

