def integer_sqrt(n):
    """Return floor(sqrt(n)) using only integer arithmetic."""
    if n < 0:
        raise ValueError("negative argument")
    if n == 0:
        return 0
    # Initial guess using a floating-point approximation, then corrected.
    x = int(n ** 0.5)
    # Adjust downward if we overestimated.
    while (x + 1) * (x + 1) <= n:
        x += 1
    while x * x > n:
        x -= 1
    return x

