def isqrt(n: int) -> int:
    """Integer square root using only built‑in arithmetic and os.path."""
    if n < 0:
        raise ValueError("isqrt argument must be non‑negative")
    if n == 0:
        return 0
    # Initial guess: use the bit length of the number.
