    # 2 ** ((n.bit_length() + 1) // 2).
    x = 1 << ((n.bit_length() + 1) // 2)
    # Newton's method (Heron's method) converges quickly.
    while True:
        y = (x + n // x) // 2
        if y >= x:
            return x
        x = y

