import sys

S = ["0","1","-1","+1","  12  ","\t12\n","1_0","1__0","_1","1_","-1_0","+_1",
     "0x1f","0X1F","0b101","0B101","0o17","0O17","0xg","0b2","0o8",
     "12","007","-007","ff","FF","z","Z","zz","10","1z","-ff","+FF",
     "","   ","-","+","--1","1 2","1.0","1e3"," -  1","1 "," " ,
     "٠١","１０","٣","১২3","2147483648","-9223372036854775808","9223372036854775807"]
for i, s in enumerate(S):
    if any(ord(c) > 126 for c in s):
        # build a bytes repr without calling repr on the string directly
        # start with the opening quote character
        if s and s[0] == "'":
            quote = "'"
        elif s and s[0] == '"':
            quote = '"'
        else:
            quote = "'"
        # escape non-ASCII bytes as \xHH, keep printable ASCII as-is
        parts = []
        parts.append(quote)
        for c in s:
            code = ord(c)
            if code > 126:
                parts.append('\\x{:02x}'.format(code))
            elif code == ord('\\'):
                parts.append('\\\\')
            elif code == ord(quote):
                parts.append('\\' + quote)
            elif code < 32:
                # control characters: \n, \t, etc.
                parts.append('\\' + {10: 'n', 13: 'r', 9: 't'}.get(code, 'x{:02x}'.format(code)))
            else:
                parts.append(chr(code))
        parts.append(quote)
        print(i, ''.join(parts), '[' + ', '.join('[hex(ord(c)) for c in s]' for _ in [1]) + ']')
    else:
        print(i, repr(s), [hex(ord(c)) for c in s])

