import sys

def count_nonblank_lines(lines):
    """Return the number of lines that are not blank (empty or only whitespace)."""
    count = 0
    for line in lines:
        # strip removes leading and trailing whitespace; if result is non‑empty → non‑blank
        if line.strip():
            count += 1
    return count

def main():
    # Read all lines from standard input, keeping the newline characters.
    raw_lines = sys.stdin.readlines()
    result = count_nonblank_lines(raw_lines)
    print(result)

if __name__ == "__main__":
    main()

