import os

def fill(s, width):
    words = s.split()
    lines = []
    current = ""
    for w in words:
        if current:
            needed = len(current) + 1 + len(w)
        else:
            needed = len(w)
        if needed <= width:
            if current:
                current += " " + w
            else:
                current = w
        else:
            lines.append(current)
            current = w
    if current:
        lines.append(current)
    return "\n".join(lines)

def dedent(s):
    lines = s.split("\n")
    min_indent = None
    for line in lines:
        if line.strip():
            spaces = len(line) - len(line.lstrip(" "))
            if min_indent is None or spaces < min_indent:
                min_indent = spaces
    if min_indent is None:
        return s
    result = []
    for line in lines:
        if line.strip():
            result.append(line[min_indent:])
        else:
            result.append(line)
    return "\n".join(result)

