import re
import ast
import sys

def safe_eval(expr, allowed_globals=None):
    """
    Safely evaluate a Python expression string without using eval().
    Only handles simple literals and attribute/item access needed for
    regex patterns and results.
    """
    if allowed_globals is None:
        allowed_globals = {'re': re}

    # Parse the expression into an AST
    tree = ast.parse(expr, mode='eval')

    # Walk the AST and evaluate only safe nodes
    return _eval_node(tree.body, allowed_globals)

def _eval_node(node, allowed_globals):
    """Recursively evaluate AST nodes."""
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        if node.id in allowed_globals:
            return allowed_globals[node.id]
        raise NameError(f"name '{node.id}' is not allowed")
    elif isinstance(node, ast.Attribute):
        value = _eval_node(node.value, allowed_globals)
        if isinstance(value, re.Pattern):
            return getattr(value, node.attr)
        raise AttributeError(f"cannot get attribute '{node.attr}'")
    elif isinstance(node, ast.Subscript):
        value = _eval_node(node.value, allowed_globals)
        index = _eval_node(node.slice, allowed_globals)
        return value[index]
    elif isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.UAdd):
        return +_eval_node(node.operand, allowed_globals)
    elif isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
        return -_eval_node(node.operand, allowed_globals)
    elif isinstance(node, ast.BinOp):
        left = _eval_node(node.left, allowed_globals)
        right = _eval_node(node.right, allowed_globals)
        if isinstance(node.op, ast.Add):
            return left + right
        elif isinstance(node.op, ast.Sub):
            return left - right
        elif isinstance(node.op, ast.Mult):
            return left * right
        elif isinstance(node.op, ast.Div):
            return left / right
        elif isinstance(node.op, ast.Mod):
            return left % right
        elif isinstance(node.op, ast.Pow):
            return left ** right
        elif isinstance(node.op, ast.FloorDiv):
            return left // right
        elif isinstance(node.op, ast.MatMult):
            return left @ right
        else:
            raise ValueError(f"unsupported binary operation: {ast.dump(node.op)}")
    elif isinstance(node, ast.Compare):
        left = _eval_node(node.left, allowed_globals)
        for op, comparator in zip(node.ops, node.comparators):
            right = _eval_node(comparator, allowed_globals)
            if isinstance(op, ast.Eq):
                if not (left == right):
                    return False
            elif isinstance(op, ast.NotEq):
                if not (left != right):
                    return False
            elif isinstance(op, ast.Lt):
                if not (left < right):
                    return False
            elif isinstance(op, ast.LtE):
                if not (left <= right):
                    return False
            elif isinstance(op, ast.Gt):
                if not (left > right):
                    return False
            elif isinstance(op, ast.GtE):
                if not (left >= right):
                    return False
            else:
                raise ValueError(f"unsupported comparison: {ast.dump(op)}")
            left = right
        return True
    elif isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = True
            for value in node.values:
                result = result and _eval_node(value, allowed_globals)
            return result
        elif isinstance(node.op, ast.Or):
            result = False
            for value in node.values:
                result = result or _eval_node(value, allowed_globals)
            return result
    elif isinstance(node, ast.IfExp):
        test = _eval_node(node.test, allowed_globals)
        if test:
            return _eval_node(node.body, allowed_globals)
        else:
            return _eval_node(node.orelse, allowed_globals)
    elif isinstance(node, ast.Call):
        # Handle re module function calls
        func = _eval_node(node.func, allowed_globals)
        args = [_eval_node(a, allowed_globals) for a in node.args]
        keywords = {kw.arg: _eval_node(kw.value, allowed_globals) for kw in node.keywords}
        return func(*args, **keywords)
    else:
        raise ValueError(f"unsupported AST node: {type(node).__name__}")

def t(expr):
    try:
        # Use safe_eval instead of eval
        result = safe_eval(expr, {'re': re})
        print("%-56s => %r" % (expr, result))
    except BaseException as e:
        print("%-56s !! %s: %s" % (expr, type(e).__name__, e))

